#!/usr/bin/env python3
# Some portions generated by Codex. Summarize only completed, witnessed benchmark runs.
import pathlib,json,statistics,sys
root=pathlib.Path(__file__).resolve().parents[3]
d=root/'experiments/overlay/workbench-e2e'
comparison = len(sys.argv) > 1 and sys.argv[1] == 'previous-best'
control = 'baseline' if comparison else 'off'
prefix = 'memo-best-abba-' if comparison else 'memo-entry-abba-'
rows=[]
for arm in ['1-'+control,'2-on','3-on','4-'+control]:
 p=d/f'{prefix}{arm}.json';r=json.loads(p.read_text())
 assert r['witnessesPassed']
 rows.append({'arm':arm,'firstRowMs':r['firstRowMs'],'batchMs':r['batchMs'],'endMs':r['endMs'],'rows':r['rows'],'bytes':r['bytes'],'totalCount':r['terminal']['total-result-count'],'rssKiB':r['peakSampledServerRSSKiB']})
out={'runs':rows,'means':{}}
for mode in [control,'on']:
 subset=[r for r in rows if r['arm'].endswith(mode)]
 out['means'][mode]={k:statistics.mean(r[k] for r in subset) for k in ['firstRowMs','batchMs','endMs','rssKiB']}
out['percentLessElapsed']={k:100*(1-out['means']['on'][k]/out['means'][control][k]) for k in ['firstRowMs','batchMs','endMs']}
print(json.dumps(out,indent=2))
